<?php
use App\Core\DB;use App\Core\Auth;use App\Core\Csrf;use App\Core\U;use App\Core\Audit;use App\Core\Secret;use App\Core\Site;use App\Services\ReservationService;use App\Services\GeminiService;use App\Services\UploadService;use App\Services\ICalService;use App\Controllers\WhatsappController;
if (!defined('SUITES_PAGE_ENTRY')) { http_response_code(404); exit; }

  Auth::requirePerm('guests.view');
  $edit=null;if(isset($_GET['id'])){$q=$pdo->prepare("SELECT * FROM guests WHERE id=?");$q->execute([(int)$_GET['id']]);$edit=$q->fetch();}
  if($_SERVER['REQUEST_METHOD']==='POST'){
    Csrf::check();$id=(int)($_POST['id']??0);
    $vals=[trim($_POST['name']),trim($_POST['document']),$_POST['birth_date']?:null,trim($_POST['phone']),trim($_POST['whatsapp']),trim($_POST['email']),trim($_POST['address']),trim($_POST['city']),trim($_POST['state']),trim($_POST['country']),trim($_POST['nationality']),trim($_POST['language']),$_POST['notes'],$_POST['accessibility'],(int)$_POST['children'],isset($_POST['privacy_consent'])?1:0];
    if($id){$vals[]=$id;$pdo->prepare("UPDATE guests SET name=?,document=?,birth_date=?,phone=?,whatsapp=?,email=?,address=?,city=?,state=?,country=?,nationality=?,language=?,notes=?,accessibility=?,children=?,privacy_consent=?,updated_at=NOW() WHERE id=?")->execute($vals);}
    else{$pdo->prepare("INSERT INTO guests(name,document,birth_date,phone,whatsapp,email,address,city,state,country,nationality,language,notes,accessibility,children,privacy_consent,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())")->execute($vals);$id=(int)$pdo->lastInsertId();}
    Audit::log('guest.save','guest',$id);U::flash('ok','Hóspede salvo.');U::redirect('index.php?p=guests&id='.$id);
  }
  $gs=$pdo->query("SELECT * FROM guests ORDER BY id DESC LIMIT 500")->fetchAll();
  $reservations=$pdo->query("SELECT r.id,r.guest_id,r.code,rm.name room_name,r.checkin,r.checkout,r.status,cl.closed_at FROM reservations r JOIN rooms rm ON rm.id=r.room_id LEFT JOIN suites_folio_closures cl ON cl.reservation_id=r.id ORDER BY r.id DESC LIMIT 2000")->fetchAll();
  $byGuest=[];foreach($reservations as $x)$byGuest[(int)$x['guest_id']][]=['id'=>(int)$x['id'],'code'=>(string)$x['code'],'room'=>(string)$x['room_name'],'dates'=>(string)$x['checkin'].' a '.(string)$x['checkout'],'status'=>(string)$x['status'],'closed'=>$x['closed_at']!==null];
  $catalog=$pdo->query("SELECT id,name,category,unit,price FROM suites_catalog_items WHERE active=1 ORDER BY category,name")->fetchAll();
  $guestPayload=[];foreach($gs as $g){$guestPayload[(int)$g['id']]=$g;}
  $canConsume=Auth::isAdmin()||Auth::isSuperAdmin()||Auth::can('reservations.manage');
  $h=adminTitle('Hóspedes');
  $h.='<style>
.guest-list-head{display:flex;justify-content:flex-end;margin-bottom:12px}.guest-table{width:100%;border-collapse:collapse}.guest-table th,.guest-table td{text-align:left;padding:10px;border-bottom:1px solid #e0e9e4}.guest-table td:last-child{white-space:nowrap}.guest-actions{display:flex;gap:6px;flex-wrap:wrap}.guest-modal{border:1px solid #a8c1b5;border-radius:13px;padding:0;width:min(720px,calc(100vw - 24px));max-height:90dvh;background:white;color:#183e35;box-shadow:0 25px 75px #122c2866;overflow:hidden}.guest-modal::backdrop{background:#0e281f99}.guest-modal[open]{display:flex;flex-direction:column}.guest-modal-head{padding:14px 18px;border-bottom:1px solid #dce8df;display:flex;justify-content:space-between;align-items:center}.guest-modal-head h2{font-size:17px;margin:0}.guest-modal-body{padding:18px;overflow-y:auto;min-height:0}.guest-modal form{display:grid;gap:13px}.guest-modal .grid3{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:11px}.guest-modal form input:not([type=checkbox]),.guest-modal form textarea,.guest-modal form select{max-width:100%;box-sizing:border-box;width:100%}.guest-modal .guest-close{background:#fff;border:1px solid #b8cbc0;border-radius:8px;padding:5px 11px;cursor:pointer}@media(max-width:650px){.guest-modal .grid3{grid-template-columns:1fr}.guest-table{font-size:12px}.guest-modal-body{padding:12px}}
  </style>';
  $h.='<div class="guest-list-head"><button type="button" class="btn" id="guestNew">'.panelCardIcon('home').' Adicionar hóspede</button></div>';
  $h.='<section class="card"><div class="table-scroll"><table class="guest-table"><thead><tr><th>Nome</th><th>E-mail</th><th>WhatsApp</th><th>Reservas</th><th>Ações</th></tr></thead><tbody>';
  foreach($gs as $g){
   $id=(int)$g['id'];$rCount=count($byGuest[$id]??[]);
   $h.='<tr><td>'.U::e($g['name']).'</td><td>'.U::e($g['email']).'</td><td>'.U::e($g['whatsapp']).'</td><td>'.$rCount.'</td><td><div class="guest-actions"><button type="button" class="btn secondary small" data-guest-profile="'.$id.'">Ficha</button><button type="button" class="btn secondary small" data-guest-edit="'.$id.'">Editar</button></div></td></tr>';
  }
  if(!$gs)$h.='<tr><td colspan="5">Nenhum hóspede cadastrado.</td></tr>';
  $h.='</tbody></table></div></section>';
  $h.='<dialog class="guest-modal" id="guestEditor" aria-label="Cadastro de hóspede"><header class="guest-modal-head"><h2 id="guestEditorTitle">Novo hóspede</h2><button type="button" class="guest-close" data-guest-close>×</button></header><div class="guest-modal-body"><form method="post">'.Csrf::field().'<input type="hidden" name="id" id="guestId" value=""><div class="grid3">'.row('Nome completo','name').row('Documento','document').row('Nascimento','birth_date','','date').row('Telefone','phone').row('WhatsApp','whatsapp').row('E-mail','email','','email').row('Endereço','address').row('Cidade','city').row('Estado','state').row('País','country').row('Nacionalidade','nationality').row('Idioma','language').row('Crianças','children',0,'number').'</div>'.row('Observações','notes','','textarea').row('Necessidades de acessibilidade','accessibility','','textarea').row('Consentimento de privacidade registrado','privacy_consent',0,'checkbox').'<button type="submit">Salvar hóspede</button></form></div></dialog>';
  $h.='<dialog class="guest-modal" id="guestProfile" aria-label="Ficha e consumo do hóspede"><header class="guest-modal-head"><h2 id="guestProfileTitle">Ficha do hóspede</h2><button type="button" class="guest-close" data-guest-close>×</button></header><div class="guest-modal-body"><p id="guestProfileInfo"></p><h3>Reservas e comandas</h3><div id="guestReservationLinks"></div>';
  if($canConsume){
   $h.='<form action="/painel/?p=comandas" method="post" id="guestConsumptionForm">'.Csrf::field().'<input type="hidden" name="action" value="add_catalog"><label>Reserva / apartamento<select name="reservation_id" id="guestReservation" required></select></label><label>Produto ou serviço<select name="catalog_id" required><option value="">Selecione o item</option>';
   foreach($catalog as $x)$h.='<option value="'.(int)$x['id'].'">'.U::e(($x['category']==='bar'?'Bar':'Serviço').' · '.$x['name'].' · '.money((float)$x['price']).'/'.$x['unit']).'</option>';
   $h.='</select></label><label>Quantidade<input type="number" name="qty" value="1" min="0.001" max="10000" step="0.001" required></label><button type="submit"'.(!$catalog?' disabled':'').'>Adicionar à comanda</button>';
   if(!$catalog)$h.='<p>Primeiro cadastre itens em <a href="/painel/products_services.php">Produtos e Serviços</a>.</p>';
   $h.='</form>';
  }
  $h.='</div></dialog>';
  $h.='<script type="application/json" id="guestData">'.json_encode(['guests'=>$guestPayload,'reservations'=>$byGuest],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_INVALID_UTF8_SUBSTITUTE).'</script>';
  $h.='<script>(()=>{const d=JSON.parse(document.getElementById("guestData").textContent),editor=document.getElementById("guestEditor"),profile=document.getElementById("guestProfile"),form=editor.querySelector("form");const closeButtons=document.querySelectorAll("[data-guest-close]");for(const b of closeButtons)b.addEventListener("click",()=>b.closest("dialog").close());for(const modal of [editor,profile])modal.addEventListener("click",e=>{if(e.target===modal)modal.close()});const fields=["name","document","birth_date","phone","whatsapp","email","address","city","state","country","nationality","language","children","notes","accessibility","privacy_consent"];function edit(g){form.reset();for(const key of fields){const x=form.elements.namedItem(key);if(!x)continue;if(x.type==="checkbox")x.checked=!!Number(g?.[key]||0);else x.value=g?.[key]??(key==="children"?"0":"");}document.getElementById("guestId").value=g?.id??"";document.getElementById("guestEditorTitle").textContent=g?"Editar hóspede":"Novo hóspede";editor.showModal();}document.getElementById("guestNew").addEventListener("click",()=>edit(null));document.querySelectorAll("[data-guest-edit]").forEach(b=>b.addEventListener("click",()=>edit(d.guests[b.dataset.guestEdit])));document.querySelectorAll("[data-guest-profile]").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.guestProfile,g=d.guests[id],rs=d.reservations[id]||[];if(!g)return;document.getElementById("guestProfileTitle").textContent="Ficha · "+g.name;document.getElementById("guestProfileInfo").textContent=[g.email,g.whatsapp].filter(Boolean).join(" · ");const links=document.getElementById("guestReservationLinks");links.replaceChildren();const select=document.getElementById("guestReservation");if(select)select.replaceChildren();for(const r of rs){const line=document.createElement("p"),a=document.createElement("a");a.href="/painel/comandas.php?reservation_id="+encodeURIComponent(r.id);a.textContent=r.code+" · "+r.room+" · "+r.dates+(r.closed?" (fechada)":"");line.appendChild(a);links.appendChild(line);if(select&&!r.closed){const opt=document.createElement("option");opt.value=r.id;opt.textContent=r.code+" · "+r.room;select.appendChild(opt);}}if(!rs.length){links.textContent="Sem reservas vinculadas. É necessário ter uma reserva para lançar consumo.";}const submit=profile.querySelector("#guestConsumptionForm button[type=submit]");if(submit)submit.disabled=!select?.options.length||!profile.querySelector("#guestConsumptionForm select[name=catalog_id]")?.options.length||profile.querySelector("#guestConsumptionForm select[name=catalog_id]")?.options.length===1;profile.showModal();}));})();</script>';
  render('Hóspedes',$h);exit;
